def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    try:
        field_names = [f[0] for f in fields]
        annotations = {f[0]: f[1] for f in fields}

        def __init__(self, *args, **kwargs):
            self._values = {}
            for name, value in zip(field_names, args):
                self._values[name] = value
            for key, value in kwargs.items():
                if key in field_names:
                    self._values[key] = value

        def __repr__(self):
            field_strs = []
            for name, value in self._values.items():
                field_strs.append(f"{name}={value!r}")
            if self._srid is not None:
                field_strs.append(f"srid={self._srid!r}")
            return f"{name}({', '.join(field_strs)})"

        def __hash__(self):
            return hash((tuple(self._values.values()), self._srid))

        def __eq__(self, other):
            if not isinstance(other, type(self)):
                return NotImplemented
            return self._values == other._values and self._srid == other._srid

        new_class = type(name, (object,), {
            '__init__': __init__,
            '__repr__': __repr__,
            '__hash__': __hash__,
            '__eq__': __eq__,
            '__annotations__': annotations
        })

        new_class._srid = srid_map.get(name)

        for field_name, field_type in fields:
            def make_property(field_name):
                def getter(self):
                    return self._values.get(field_name)

                def setter(self, value):
                    self._values[field_name] = value

                return property(getter, setter)

            setattr(new_class, field_name, make_property(field_name))

        return new_class
    except Exception as e:
        raise e

