def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        order = deque()

        def _key(is_wrapped, *args, **kwargs):
            if is_wrapped:
                args = args[1:]
            key = args
            if typed:
                key = tuple(key)
            else:
                key = tuple(key)
            key = (key, frozenset(kwargs.items()))
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal cache, order
            # Generate the cache key
            if typed:
                key = _key(True, *args, **kwargs)
            else:
                key = _key(False, *args, **kwargs)

            current_time = timer()

            # If key exists in cache
            if key in cache:
                # Check if the entry is expired
                value, insertion_time = cache[key]
                if current_time - insertion_time > ttl:
                    # Expired: remove from cache and order
                    del cache[key]
                    if key in order:
                        try:
                            order.remove(key)
                        except ValueError:
                            pass
                    # Fall through to calculation below
                else:
                    # Valid: update order and return
                    if key in order:
                        order.remove(key)
                    order.appendleft(key)
                    return value

            # Calculate result
            result = func(*args, **kwargs)

            # Store in cache and order
            cache[key] = (result, current_time)
            order.appendleft(key)

            # Evict least recently used if over maxsize
            if len(cache) > maxsize:
                while order:
                    lru_key = order.pop()
                    if lru_key in cache:
                        del cache[lru_key]
                        break

            return result

        # Expose cache management
        wrapper.cache_clear = lambda: (cache.clear(), order.clear())

        return wrapper
    return decorator

