def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    if not classes:
        return []

    bases = classes[0]
    rest = classes[1:]

    for cls in rest:
        if issubclass(cls, bases):
            continue
        elif issubclass(bases, cls):
            bases = cls
        else:
            raise TypeError("bases cannot be reduced")
    return [bases]

