def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, (str, int, float)):
        raise TypeError("version must be a string, int, or float")

    logical_path_map = {}
    for logical_path, file_info in inventory.items():
        if not isinstance(file_info, (list, tuple, set)):
            continue
        version_files = []
        for file_entry in file_info:
            # Assuming file_entry is a tuple or list representing a version-specific file
            if isinstance(file_entry, (list, tuple)) and len(file_entry) > 0:
                # Assuming the first element is the version and the second is the file path
                if file_entry[0] == version:
                    version_files.append(file_entry[1] if len(file_entry) > 1 else file_entry[0])
        if version_files:
            logical_path_map[logical_path] = set(version_files)
    return logical_path_map

