        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Check if fixity block is empty
        if not isinstance(fixity, dict):
            return [ValueError("Fixity block must be a dictionary")]

        # Check if fixity block is well-formed
        errors = []
        for key, value in fixity.items():
            if not isinstance(value, dict):
                errors.append(ValueError("Fixity entries must be dictionaries"))
                continue
            # Check for required fields
            if 'file_name' not in value:
