def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if not hasattr(self, 'to_dict'):
        raise AttributeError("Object must have a 'to_dict' method to generate a pretty representation.")

    # Convert the object to a dictionary
    obj_dict = self.to_dict()

    # Helper function to convert a dictionary to a formatted string
    def format_dict(d, indent_level=0):
        indent_str = '  ' * indent_level
        result = []
        for key, value in d.items():
            if isinstance(value, dict):
                result.append("{}{}: \n{}".format(indent_str, key, format_dict(value, indent_level + 1)))
            elif isinstance(value, list):
                result.append("{}{}: [".format(indent_str, key))
                for item in value:
                    if isinstance(item, dict):
                        result.append('\n{}'.format(format_dict(item, indent_level + 2)))
                    else:
                        result.append("{}{}".format(indent_str + '  ', item))
                result.append("{}]".format(indent_str))
            else:
                result.append("{}{}: {}".format(indent_str, key, repr(value) if debug else value))
        return '\n'.join(result)

    # Generate the pretty formatted string
    pretty_str = format_dict(obj_dict, indent)

    # Add indentation if the 'indent' parameter is greater than 0
    if indent > 0:
        pretty_str = '\n'.join(indent_str + line for line in pretty_str.split('\n'))

    return pretty_str

