def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    argst = tuple(args)
    # Special-case A & (A | B) for performance.
    for i, arg in enumerate(args):
        for sub in arg.args:
            if sub.name == 'Or':
                for subsub in sub.args:
                    if subsub.name == arg.name:
                        return [subsub]
            if sub == arg:
                return [sub]
            if sub.name == 'Not':
                subsub, = sub.args
                if subsub == arg:
                    return [arg & sub.this]
    for i, arg in enumerate(args):
        for sub in arg.args:
            if sub.name == 'And':
                for subsub in sub.args:
                    if subsub == arg:
                        return [sub]
            if sub == arg:
                return [sub]
            if sub.name == 'Not':
                subsub, = sub.args
                if subsub == arg:
                    return [arg | sub.this]
    return list(argst)

