def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        root = self.storage_root
        if root is None:
            raise ValueError("Storage root is not initialized")

        def _validate_node(node, path=""):
            nonlocal num_objects, good_objects

            if node is None:
                if show_warnings:
                    print(f"Warning: None node found at path {path}")
                return

            num_objects += 1

            is_valid = True

            if validate_objects:
                if not hasattr(node, 'name'):
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object at path {path} does not have a 'name' attribute")

            if check_digests and hasattr(node, 'digest'):
                try:
                    digest_val = node.digest
                    # Assume digest must be non-empty and of type str or bytes
                    if not digest_val or not isinstance(digest_val, (str, bytes)):
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: Invalid digest at path {path}")
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Exception while checking digest at path {path}: {e}")

            if is_valid:
                good_objects += 1

            # Recurse into children if they exist
            children = getattr(node, 'children', None)
            if children is not None:
                if isinstance(children, dict):
                    for key, child in children.items():
                        child_path = f"{path}/{key}" if path else key
                        _validate_node(child, child_path)
                elif isinstance(children, (list, tuple)):
                    for i, child in enumerate(children):
                        child_path = f"{path}/{i}" if path else str(i)
                        _validate_node(child, child_path)
                elif isinstance(children, dict):
                    for key, child in children.items():
                        child_path = f"{path}/{key}"
                        _validate_node(child, child_path)

        _validate_node(root)

    except (ValueError, AttributeError, TypeError) as e:
        if show_warnings:
            print(f"Validation error: {e}")
        # Return counts collected so far
        return num_objects, good_objects

    return num_objects, good_objects

