def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        self.version_digests_inventories = {}
        root_inventory_digests = self._root_inventory_digests
        for version_dir in version_dirs:
            if not re.match(r"^[0-9]+$", version_dir):
                raise ValueError(f"Invalid version directory name: {version_dir}")
            inventory_path = os.path.join(self._repo_root, version_dir, "inventory.json")
            if os.path.exists(inventory_path):
                with open(inventory_path, "r") as f:
                    inventory = json.load(f)
                if "digests" in inventory and isinstance(inventory["digests"], dict):
                    self.version_digests_inventories[int(version_dir)] = inventory["digests"]
                    # Update root inventory digests with any new digests from this version
                    for path, digest in inventory["digests"].items():
                        if path not in root_inventory_digests or root_inventory_digests[path] != digest:
                            root_inventory_digests[path] = digest
            else:
                # Optionally log a warning for missing inventory
                # Note: do not raise an error, just continue
                pass

