def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_by_subparser = {}
    remaining_arguments = list(unparsed_arguments)
    for name, subparser in subparsers.items():
        try:
            parsed_args, unparsed_args = subparser.parse_known_args(remaining_arguments)
        except SystemExit:
            continue
        if parsed_args:
            parsed_by_subparser[name] = parsed_args
            remaining_arguments = unparsed_args
        else:
            continue
    return parsed_by_subparser, remaining_arguments

