def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    result = set()
    queue = [cls]

    while queue:
        current_class = queue.pop()
        for sub in current_class.__subclasses__():
            if sub not in result:
                result.add(sub)
                queue.append(sub)

    return result

