def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import platform as _platform
        p = 1 if _platform.system() != 'Windows' else 0
    else:
        p = int(platform) if platform in ('1', '0') else platform
    if p not in (1, 0):
        raise ValueError(
            "platform must be 'this', 1 (POSIX), or 0 (Windows/CMD)")
    if not isinstance(s, str):
        raise TypeError("argument 1 must be a string")
    if p == 1:
        # POSIX: split on whitespace, respect double/single quotes
        pat = re.compile(
            r'(?s:([^\s\x27\x22`]+))?|(?s:\x27([^\x27]*))\x27|(?s:\x22([^\x22]*)\x22)',
        )
        tokens = []
        for m in pat.finditer(s):
            if m.group(1) is not None:
                tokens.append(m.group(1))
            elif m.group(2) is not None:
                tokens.append(m.group(2))
            else:
                tokens.append(m.group(3))
        return tokens
