def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    frequency = frequency.strip()
    if not frequency:
        raise ValueError("Frequency string cannot be empty")

    # Split into number and unit
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Frequency must be in the format 'number unit'")

    num_str, unit = parts

    # Parse the number
    try:
        num = int(num_str)
    except ValueError:
        # Try float in case decimals are allowed
        try:
            num = float(num_str)
        except ValueError:
            raise ValueError(f"Cannot parse number: {num_str}")

    # Validate and convert unit
    unit_lower = unit.lower()
    if unit_lower in ('second', 'seconds', 'sec', 'secs', 's'):
        kwargs = {'seconds': num}
    elif unit_lower in ('minute', 'minutes', 'min', 'mins', 'm'):
        kwargs = {'minutes': num}
    elif unit_lower in ('hour', 'hours', 'hr', 'hrs', 'h'):
        kwargs = {'hours': num}
    elif unit_lower in ('day', 'days', 'd'):
        kwargs = {'days': num}
    elif unit_lower in ('week', 'weeks', 'w'):
        kwargs = {'weeks': num}
    elif unit_lower in ('month', 'months', 'mo') or unit_lower in ('year', 'years', 'yr', 'yrs', 'y'):
        # Approximate months and years since timedelta doesn't directly support them
        # 1 year = 365.2425 days, 1 month ~ 30.436875 days (365.2425/12)
        if unit_lower in ('month', 'months', 'mo'):
            days = num * 30.436875
        else:
            days = num * 365.2425
        return datetime.timedelta(days=days)
    else:
        raise ValueError(f"Unsupported time unit: {unit}")

    return datetime.timedelta(**kwargs)

