def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    try:
        proc = subprocess.run(
            [sys.executable, "-c",
             "import {} as m; m.{}(*{})".format(func.__module__,
          func.__name__,
          ":".join(map(str, args)))
         ],
    timeout=timeout,
    stdout=subprocess.PIPE
    , stderr=subprocess.PIPE
    , env=extra_env
)
        if proc.returncode != 0:
            try:
                stderr = (
                        verify.blank_if_none(proc.stderr.decode())
                        if isinstance(proc.stderr, bytes)
                        else ""
                )
            except AttributeError:
                stderr = ""
            try:
                stdout = (
                        verify.blank_if_none(proc.stdout.decode())
                        if isinstance(proc.stdout, bytes)
                        else ""
                )
            except AttributeError:
                stdout = ""
            cmdline = " ".join(
                [sys.executable, "-c", "import {} as m; m.{}(*{})".format(
                    func.__module__,
                    func.__name__,
                    "".join(["'" + arg + "', " for arg in args])
                )])
            raise RuntimeError("Command {} exited with code {}.\n{}{}".format(cmdline, proc.returncode, stdout, stderr))
        return proc
    except TimeoutError as e:
        raise TimeoutError("Command executed is {} exceeded the timeout of {} seconds.".format(e, timeout))

