def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if isinstance(matcher, dict):
        name = matcher.get("name")
        default = matcher.get("default")
    elif isinstance(matcher, (list, tuple)):
        name, default = matcher[0], matcher[1] if len(matcher) > 1 else None
    else:
        name, default = matcher, None

    if name is None or not isinstance(name, str):
        raise ValueError("Environment variable name must be a non-None string")

    value = os.environ.get(name)

    if value is not None:
        return value

    if default is not None:
        return default

    raise EnvironmentError(f"Environment variable '{name}' not found and no default provided")

