        warning = (
            "Argument {} has an implicit encoding {}".format(dt_str, "ascii")
        )
        warnings.warn(warning, RuntimeWarning)
    s = dt_str.decode('ascii')

    try:
        year_str = s[0:4]
        year = int(year_str)
        if len(s) == 4:
            return datetime.year(year)

        month_str = s[5:7]
        month = int(month_str)
        if len(s) == 7:
            return Month(year=year, month=month)

        day_str = s[8:10]
        day = int(day_str)
        if len(s) == 10:
            return Day(year=year, month=month, day=day)

        # Time
        time_str = s[10:]
        hour = int(time_str[0:2])
        if len(time_str) == 2:
            if hour == 24:
                hour = 0
            return Time(year=year, month=month, day=day, hour=hour)

        minute_str = time_str[3:5]
        minute = int(minute_str)
        if len(time_str) == 5:
            if hour == 24:
                hour = 0
            return Time(year=year, month=month, day=day, hour=hour, minute=minute)

