def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing as JSON first (new format)
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XRD (old format)
        xrd = ET.fromstring(document.encode("utf-8"))
        result = {}
        for link in xrd.findall("link"):
            rel = link.get("rel")
            template = link.get("template")
            if rel == "lrdd":
                result["lrdd"] = template
            elif rel == "hcard":
                result["hcard_url"] = link.get("href")
        return result

