def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        specs = []
        # Retrieve the parser for the specific command
        parser = self.get_parser(command_name)
        if parser is None:
            return specs

        # Iterate over the action groups to find all options
        for action_group in parser._action_groups:
            for action in action_group._group_actions:
                # Filter to only include option-string based actions (flags/arguments)
                if action.option_strings:
                    specs.append(action)

        return specs
    except Exception as e:
        # Return empty list if an unexpected error occurs to maintain robustness
        return []

