def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, 'valid_min') or not hasattr(self, 'valid_max'):
        return args

    for value in args:
        if not (self.valid_min <= value <= self.valid_max):
            raise ValueError(
                "Argument value must be between %s and %s" % (
                    self.valid_min, self.valid_max
                )
            )

    return args

